Q: How to unnest a list-column as new rows in pre-existing columns? A: <pre class="lang-r prettyprint-override"><code>library(tidyverse)

ex %&gt;%
  mutate(z = map(z, \(z) if (is.data.frame(z)) z else NULL)) |&gt;
  pmap_dfr(\(x, y, z) bind_rows(tibble(x, y), z))  # or pmap(...) |&gt; bind_rows()

#&gt; # A tibble: 7 × 2
#&gt;   x           y
#&gt;   &lt;chr&gt;   &lt;dbl&gt;
#&gt; 1 Q      0.633 
#&gt; 2 F      0.5   
#&gt; 3 E      0.404 
#&gt; 4 A     -0.106 
#&gt; 5 J      1.51  
#&gt; 6 A     -0.2   
#&gt; 7 D     -0.0947
</code></pre>
<p>or</p>
<pre class="lang-r prettyprint-override"><code>set_names(ex$z, seq_len(nrow(ex))) |&gt; 
  keep(is.data.frame) |&gt; 
  bind_rows(.id = &quot;id&quot;) |&gt; 
  mutate(id = as.integer(id)) |&gt;
 (\(z_rows){
   ex |&gt;
     select(x, y) |&gt;
     rowid_to_column(&quot;id&quot;) |&gt; 
     bind_rows(z_rows) |&gt;
     arrange(id) |&gt; 
     select(-id)})()
</code></pre>
